-- Run ONCE in phpMyAdmin (SQL tab) on an existing database. Safe to re-run: skips places that already exist.
-- Photos: drop <slug>.jpg into assets/images/destinations/ (e.g. dambulla.jpg, adams-peak.jpg) and they appear automatically.

INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Dambulla','Cultural Triangle','Golden cave temple','Five painted cave temples filled with Buddha statues, set into a huge granite rock.','A cave monastery complex carved into a giant granite rock and used as a Buddhist temple for over 2,000 years. Five caves hold more than 150 Buddha statues and ceilings covered in painted murals, and the climb up rewards you with views across the plains.','Year-round (go early morning)','Half-day visit','UNESCO World Heritage Site','fa-place-of-worship','linear-gradient(155deg,#0E2C4C,#1E6FA8 55%,#3FA9E8)',10 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Dambulla');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Polonnaruwa','Cultural Triangle','Medieval capital','The ruined royal city of the 11th–13th centuries, with the rock-cut Gal Vihara Buddhas.','Sri Lanka''s capital from the 11th to the 13th century, now a sprawling archaeological park beside the Parakrama Samudra reservoir. The Gal Vihara rock-cut Buddha statues, the royal palace ruins and the circular Vatadage are best explored by bicycle.','Feb – Sep (dry season)','Full-day visit','UNESCO World Heritage Site','fa-landmark','linear-gradient(155deg,#0B2138,#2E9ED4)',11 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Polonnaruwa');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Horton Plains','Hill Country','World''s End cliff','A cool high plateau with a sheer 870m drop at World''s End and Baker''s Falls.','A cool, windswept national park plateau above 2,000m. A loop trail of about 9.5km leads to World''s End, a sheer drop of roughly 870 metres, and on to Baker''s Falls. Clouds roll in by mid-morning, so start at dawn for the clearest views.','Jan – Mar (clearest views)','Half-day (dawn start)','World''s End viewpoint','fa-mountain','linear-gradient(155deg,#102A44,#7FC8F5)',12 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Horton Plains');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Adam''s Peak','Hill Country','Sunrise pilgrimage','A night climb up thousands of steps to a sacred summit and dawn views.','Sri Pada, a 2,243m sacred peak revered by Buddhists, Hindus, Muslims and Christians. Pilgrims and trekkers climb thousands of steps through the night to reach the summit for sunrise, when the mountain casts a triangular shadow across the land. The climbing season runs roughly December to May.','Dec – May (pilgrimage season)','Overnight climb','Sunrise from the summit','fa-person-hiking','linear-gradient(155deg,#0E2C4C,#3FA9E8)',13 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Adam''s Peak');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Haputale','Hill Country','Tea ridge viewpoints','A quiet hill town with Lipton''s Seat and sweeping views over tea estates.','A quieter alternative to Ella, perched on a ridge on the southern edge of the hill country. Lipton''s Seat looks out over the tea estates, and on clear mornings the view stretches toward the southern plains. The Dambatenne tea factory is on the way up.','Jan – Mar (clear mornings)','1–2 days','Lipton''s Seat sunrise','fa-mug-hot','linear-gradient(155deg,#0E2C4C,#1E6FA8 55%,#3FA9E8)',14 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Haputale');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Unawatuna','South Coast','Calm crescent bay','A sheltered bay beside Galle with swimmable water and a jungle beach nearby.','A curved, sheltered bay a short ride from Galle Fort, with calm swimming for much of the dry season. Jungle Beach and the Japanese Peace Pagoda are a short distance away, and snorkelling spots lie close to shore.','Nov – Apr','2–3 days','Swimmable bay near Galle','fa-umbrella-beach','linear-gradient(155deg,#0B2138,#2E9ED4)',15 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Unawatuna');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Hikkaduwa','South Coast','Reefs & sea turtles','Coral reefs, turtles in the shallows, and beginner-friendly surf.','A lively beach town on the south-west coast known for snorkelling over coral, green sea turtles close to shore, and gentle surf breaks for beginners. Glass-bottom boats run out to the reef.','Nov – Apr','2 days','Snorkelling with turtles','fa-fish','linear-gradient(155deg,#102A44,#7FC8F5)',16 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Hikkaduwa');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Arugam Bay','South Coast','East-coast surf town','A laid-back surf town with Sri Lanka''s best-known point break.','A relaxed surf town on the east coast, home to Main Point, the island''s best-known surf break. Its season runs opposite to the south-west coast, from roughly May to September, and the birdlife of Kumana National Park is within day-trip distance.','May – Sep','3 days','Main Point surf break','fa-water','linear-gradient(155deg,#0E2C4C,#3FA9E8)',17 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Arugam Bay');
INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Udawalawe','Wildlife','Elephant safari','Open grassland where wild elephant herds are reliably seen from a jeep.','A national park of open grassland and scrub around a large reservoir, famous for dependable elephant sightings on jeep safaris. The nearby Elephant Transit Home cares for orphaned calves before they are released back into the wild.','May – Sep (dry season)','Half-day safari','Reliable elephant herds','fa-paw','linear-gradient(155deg,#0E2C4C,#1E6FA8 55%,#3FA9E8)',18 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Udawalawe');

INSERT INTO destinations (name, region, tag, short_desc, long_desc, best_time, duration, highlight, icon, gradient, sort_order)
SELECT 'Sinharaja Rainforest','Wildlife','Rainforest trek','Sri Lanka''s last big tract of primary rainforest, rich in endemic birds and wildlife.','A UNESCO-listed lowland rainforest in the south-west, home to a large share of Sri Lanka''s endemic birds, butterflies and amphibians. Guided walks follow shaded trails past streams and giant trees; expect leeches and rain, and go early for birdsong.','Jan – Apr, Aug – Sep (drier months)','1–2 days','Endemic bird watching','fa-tree','linear-gradient(155deg,#071B30,#1D6B73 60%,#8ED0F2)',19 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE name='Sinharaja Rainforest');

